<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Support;
use App\Application\Audit\AuditWriter;use App\Application\Operations\CommunicationLogService;use App\Application\Support\SupportTicketService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class SupportController{
public function store(Request$r,SupportTicketService$s){$d=$r->validate(['party_id'=>'nullable|uuid|exists:parties,id','type'=>'required|in:SUPPORT,COMPLAINT,REGULATORY_COMPLAINT','category'=>'required|string|max:64','priority'=>'required|in:LOW,NORMAL,HIGH,URGENT','subject'=>'required|string|max:200','description'=>'required|string|min:20|max:10000','idempotency_key'=>'required|string|max:100']);$out=$s->open(app(\App\Domain\Tenancy\TenantContext::class)->id(),$d,$r->user());return response()->json(['data'=>$out['ticket']],$out['created']?201:200);}
public function transition(Request$r,string$ticket,SupportTicketService$s){$d=$r->validate(['to_status'=>'required|in:TRIAGED,IN_PROGRESS,WAITING_CUSTOMER,ESCALATED,RESOLVED,CLOSED,REOPENED,CANCELLED','message'=>'required|string|min:5|max:5000','assigned_to'=>'nullable|uuid|exists:users,id']);return response()->json(['data'=>$s->transition(app(\App\Domain\Tenancy\TenantContext::class)->id(),$ticket,$d,$r->user())]);}
public function communication(Request$r,CommunicationLogService$s){$d=$r->validate(['party_id'=>'nullable|uuid','direction'=>'required|in:INBOUND,OUTBOUND','channel'=>'required|in:PHONE,SMS,EMAIL,WHATSAPP,PORTAL','purpose'=>'required|string|max:24','counterparty'=>'required|string|max:190','summary'=>'required|string|max:5000','ticket_id'=>'nullable|uuid','metadata'=>'array','occurred_at'=>'nullable|date']);$t=app(\App\Domain\Tenancy\TenantContext::class)->id();foreach(['party_id'=>'tenant_customers','ticket_id'=>'support_tickets']as$k=>$table)if(!empty($d[$k]))abort_unless(DB::table($table)->where($k==='party_id'?['tenant_id'=>$t,'party_id'=>$d[$k]]:['tenant_id'=>$t,'id'=>$d[$k]])->exists(),404);return response()->json(['data'=>['id'=>$s->record($t,$d,$r->user()->id)]],201);}}
